(ROOT/'math-labs/content.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
spec=importlib.util.spec_from_file_location('shell',ROOT/'tools/site-shell.py');shell=importlib.util.module_from_spec(spec);spec.loader.exec_module(shell)
for t in D:
 for lang in [0,1]:
  ja=lang==1; prefix='/ja' if ja else '';route=prefix+'/'+t['slug']+'/';alt=('' if ja else '/ja')+'/'+t['slug']+'/'
  esc=html.escape; nav,foot=None,None
  # Shared shell applied separately after generation.
  sections=[]
  for l in t['labs']:
   controls=''.join(f'<label>{esc(a[2 if ja else 1])} <output for="{l["id"]}-{a[0]}">{a[6]}</output><input id="{l["id"]}-{a[0]}" data-key="{a[0]}" type="range" min="{a[3]}" max="{a[4]}" step="{a[5]}" value="{a[6]}"></label>' for a in l['params'])
   sections.append(f'''<section class="experiment" id="{l['id']}" data-lab="{l['id']}"><div class="section-head"><h2>{esc(l['title'][lang])}</h2></div><p>{esc(l['body'][lang])}</p><div class="controls">{controls}</div><div class="plot" role="img" aria-label="{esc(l['title'][lang])}"></div><p class="readout" aria-live="polite"></p><div class="formula" data-tex="{esc(l['formula'],quote=True)}"></div><div class="notes"><p><strong>{'計算例' if ja else 'Worked example'}.</strong> {esc(l['example'][lang])}</p><p><strong>{'注意点' if ja else 'Watch out'}.</strong> {esc(l['caution'][lang])}</p><details><summary>{esc(l['question'][lang])}</summary><p>{esc(l['answer'][lang])}</p></details></div><a class="source" href="{l['url']}">{'参考文献' if ja else 'Reference'}: {esc(l['source'])}</a></section>''')
  links=''.join(f'<a href="#{l["id"]}">{esc(l["title"][lang])}</a>' for l in t['labs'])
  related=''.join(f'<a href="{prefix}/{u["slug"]}/">{esc(u["title"][lang])}</a>' for u in D if u!=t)
  page=f'''<!doctype html><html lang="{'ja' if ja else 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(t['title'][lang])} · Isegoria</title><meta name="description" content="{esc(t['description'][lang])}"><link rel="canonical" href="https://theisegoria.github.io{route}"><link rel="alternate" hreflang="{'en' if ja else 'ja'}" href="https://theisegoria.github.io{alt}"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/isegoria.css?v=20260915"><link rel="stylesheet" href="/analysis-atlas/vendor/katex.min.css"><link rel="stylesheet" href="/math-labs/labs.css"><script defer src="/analysis-atlas/vendor/katex.min.js"></script><script defer src="/math-labs/experience.js?v=20260919b"></script><script defer src="/assets/math-notation.js?v=20260919"></script><script defer src="/math-labs/app.js?v=20260920b"></script></head><body data-topic="{t['slug']}"><main class="math-wrap"><header class="lesson-intro"><p class="eyebrow">ISEGORIA / {'数学百科事典' if ja else 'MATH ENCYCLOPEDIA'}</p><h1>{esc(t['title'][lang])}</h1><p class="deck">{esc(t['description'][lang])}</p><p>{'前提知識' if ja else 'Before you begin'}: {esc(t['prerequisite'][lang])}</p>{'<p class="disclosure">英語原文からのAI翻訳。数式と計算モデルは両言語で共通です。</p>' if ja else ''}<nav class="lesson-nav" aria-label="{'実験' if ja else 'Experiments'}">{links}</nav><p class="method">{'予想してから操作し、計算例と問いで理解を確かめてください。グラフは数式の図示であり、証明ではありません。' if ja else 'Predict, manipulate, then check your reasoning against the example and question. Graphs illustrate the mathematics; they do not replace a proof.'}</p></header>{''.join(sections)}<section class="connections"><h2>{'次に読む' if ja else 'Continue exploring'}</h2><div class="lesson-nav">{related}</div><p><a href="{prefix}/math-encyclopedia/">{'数学百科事典に戻る' if ja else 'Back to the math encyclopedia'}</a></p></section></main><noscript>{'対話実験にはJavaScriptが必要です。本文と計算例はそのまま読めます。' if ja else 'Enable JavaScript for the experiments. Explanations and worked examples remain readable.'}</noscript></body></html>'''
  path=ROOT/route.strip('/')/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(page)
print(f'Generated {len(D)*2} pages and {sum(len(t["labs"]) for t in D)} experiments')
